#include <zephyr/ztest.h>
#include <zephyr/kernel.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;

static int main_prio;

static K_SEM_DEFINE(sema, 0, 1);

/* entry point for auxiliary thread */
static void tThread_entry(void *p1, void *p2, void *p3)
{
	/* TESTPOINT: check meta IRQ priority */
	zassert_true(k_thread_priority_get(k_current_get()) < 0,
		     "meta IRQ priority not negative");
	/* TESTPOINT: check main thread priority */
	zassert_true(k_thread_priority_get(p1) == main_prio,
		     "main thread priority wrong");
	/* Let main thread run */
	k_sem_give(&sema);
}

/**
 * @brief Test k_thread_priority_get()
 *
 * @ingroup kernel_thread_tests
 *
 * @details Create a thread with a specific priority, then get the priority
 * of the current thread and the created thread and check if they are correct.
 */
static void test_thread_priority_get(void)
{
	main_prio = k_thread_priority_get(k_current_get());

	/* create a thread with priority lower than the current thread */
	k_tid_t tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				      tThread_entry, k_current_get(), NULL, NULL,
				      main_prio + 1, 0, K_NO_WAIT);

	/* Let the new thread run */
	k_sem_take(&sema, K_FOREVER);

	/* TESTPOINT: check new thread priority */
	zassert_true(k_thread_priority_get(tid) == main_prio + 1,
		     "child thread priority wrong");

	/* cleanup */
	k_thread_abort(tid);
}

static void bad_priority_thread(void *p1, void *p2, void *p3)
{
	/* Should not execute */
	ztest_test_fail();
}

/**
 * @brief Test that creating threads with invalid priorities fails
 *
 * @ingroup kernel_thread_tests
 */
static void test_bad_priorities(void)
{
	k_tid_t tid;

	/* Min negative priority */
	tid = k_thread_create(&tdata, tstack, STACK_SIZE,
			      bad_priority_thread, NULL, NULL, NULL,
			      K_HIGHEST_THREAD_PRIO - 1, 0, K_NO_WAIT);
	zassert_is_null(tid, "thread created with too-high priority");

	/* Max positive priority */
	tid = k_thread_create(&tdata, tstack, STACK_SIZE,
			      bad_priority_thread, NULL, NULL, NULL,
			      K_LOWEST_THREAD_PRIO + 1, 0, K_NO_WAIT);
	zassert_is_null(tid, "thread created with too-low priority");
}

static volatile int busy_wait_flag;

static void busy_wait_thread_cooperative(void *p1, void *p2, void *p3)
{
	/* Let the other thread execute */
	k_yield();

	/* Now spin until the flag is set */
	while (!busy_wait_flag) {
		k_busy_wait(100); /* 100 us */
	}
}

/**
 * @brief Test k_busy_wait() in a cooperative thread
 *
 * @ingroup kernel_thread_tests
 */
static void test_busy_wait_cooperative(void)
{
	k_tid_t tid;
	int old_prio = k_thread_priority_get(k_current_get());

	busy_wait_flag = 0;

	/* Set our priority to be cooperative */
	k_thread_priority_set(k_current_get(), K_PRIO_COOP(1));

	tid = k_thread_create(&tdata, tstack, STACK_SIZE,
			      busy_wait_thread_cooperative, NULL, NULL, NULL,
			      K_PRIO_COOP(0), 0, K_NO_WAIT);

	/*
	 * Let the other thread run. It will yield back to us, and then
	 * start busy-waiting.
	 */
	k_yield();

	/*
	 * Now we are running again. The other thread is blocked in
	 * k_busy_wait(). We set the flag to let it finish.
	 */
	busy_wait_flag = 1;

	/* Wait for the other thread to terminate */
	k_thread_join(tid, K_FOREVER);

	/* Restore our priority */
	k_thread_priority_set(k_current_get(), old_prio);
}

/**
 * @brief Test k_thread_priority_get() on a NULL thread
 *
 * @ingroup kernel_thread_tests
 */
static void test_k_thread_priority_get_init_null(void)
{
#ifdef CONFIG_USERSPACE
	/* k_thread_priority_get() on a NULL thread should fail */
	ztest_set_fault_valid(true);
	(void)k_thread_priority_get(NULL);
	ztest_set_fault_valid(false);
#else
	ztest_test_skip();
#endif
}

void test_main(void)
{
	ztest_test_suite(threads_scheduling,
			 ztest_unit_test(test_bad_priorities),
			 ztest_unit_test(test_busy_wait_cooperative),
			 ztest_unit_test(test_k_thread_priority_get_init_null),
			 ztest_unit_test(test_thread_priority_get)
			 );
	ztest_run_test_suite(threads_scheduling);
}
